"""Scoped buff sounds and independent category permissions; no custom playback yet."""
from test_bufftap import test

BASE="""
local B=BuffTap; local heard=0
PlaySound=function() heard=heard+1; return true end; PlaySoundFile=PlaySound
B.db.sound=true; B.lastSound=nil; B.lastAlertSound=nil; B:Commit(nil,'test reset')
"""
test('Buff sound defaults preserve all scopes and automatic previews',BASE+"assert(B:BuffAlertEnabled('personal','motw') and B:BuffAlertEnabled('party','motw') and B:BuffAlertEnabled('raid','motw')); B:Refresh(); assert(heard==1)")
test('Muted personal buff retains actual secure action and binding',BASE+"assert(B:SetBuffAlertEnabled('personal','motw',false)); B:Refresh(); assert(heard==0 and B.action.id==5232 and B.button.attrs.spell==5232 and bindings.MOUSEWHEELDOWN); B.button.scripts.PreClick(nil,'LeftButton',true); assert(B.action and B.button.attrs.spell==5232)")
test('Muted buff does not consume sound pacing for another buff',BASE+"B:SetBuffAlertEnabled('personal','motw',false); B:Refresh(); assert(not B.lastAlertSound and not B.lastSound); aura('player',5232,'Mark of the Wild'); refresh(); assert(B.action.id==467 and heard==1)")
test('Personal mute does not mute Party or Raid versions',BASE+"B:SetBuffAlertEnabled('personal','motw',false); assert(B:BuffAlertAllowed({key='motw',target='party1'})); assert(B:BuffAlertAllowed({key='gotw',target='player',groupCast=true})); B.situationCurrent='raid'; assert(B:BuffAlertAllowed({key='gotw',target='raid1',groupCast=true}))")
test('Party and Raid mutes are independent with shared single/group family',BASE+"B:SetBuffAlertEnabled('party','motw',false); B.situationCurrent='party'; assert(not B:BuffAlertAllowed({key='gotw',target='player',groupCast=true})); assert(not B:BuffAlertAllowed({key='motw',target='party1'})); assert(B:BuffAlertAllowed({key='motw',target='player'})); B.situationCurrent='raid'; assert(B:BuffAlertAllowed({key='gotw',target='raid1',groupCast=true})); B:SetBuffAlertEnabled('raid','gotw',false); assert(not B:BuffAlertEnabled('raid','motw'))")
test('Open-world Target Nearby helpers and consumables do not inherit personal mute',BASE+"B:SetBuffAlertEnabled('personal','motw',false); for _,a in ipairs({{key='motw',target='target',quickTarget=true},{key='motw',target='nameplate1',nearby=true},{key='motw',target='player',source='cleanse'},{key='motw',target='player',source='consumable'},{key='motw',target='player',source='readiness'}}) do assert(B:BuffAlertAllowed(a)) end")
test('Personal sound remains independent of selected Solo Party Raid setup',BASE+"B:SetBuffAlertEnabled('personal','motw',false); for _,v in ipairs({'solo','party','raid'}) do B.situationCurrent=v; assert(not B:BuffAlertAllowed({key='motw',target='player'})) end")
test('Sound preference normalizes bad values and class-inapplicable keys',BASE+"B.db.buffAlerts={personal={motw={enabled=false,sound='harp',extra=true},thorns={enabled='bad',sound='not-a-sound'},ai={enabled=false}},party='bad',raid={gotw={enabled=false}}}; B:NormalizeBuffAlerts(); assert(not B:BuffAlertEnabled('personal','motw') and B.db.buffAlerts.personal.motw.sound=='harp' and not B.db.buffAlerts.personal.motw.extra); assert(not B.db.buffAlerts.personal.ai and not B.db.buffAlerts.personal.thorns and not B.db.buffAlerts.raid.gotw)")
test('Sound choices can be saved for future use but never override playback',BASE+"B.db.buffAlerts.personal.motw={enabled=true,sound='harp'}; local played; PlaySoundFile=function(path) played=path; return true end; B:Refresh(); assert(played and played:find('BuffTapCleanse',1,true) and not played:find('Harp',1,true)); B:NormalizeBuffAlerts(); assert(B.db.buffAlerts.personal.motw.sound=='harp')")
test('Combat blocks buff and category preference edits',BASE+"combat=true; assert(not B:SetBuffAlertEnabled('personal','motw',false)); assert(not B:SetAlertCategoryEnabled('reminder',false)); assert(B.db.sound and B:BuffAlertEnabled('personal','motw'))")
test('Per-buff choices survive InitDB and same-class export import',BASE+"B:SetBuffAlertEnabled('personal','motw',false); B.db.buffAlerts.personal.motw.sound='harp'; local text=B:ExportSettings(); B:SetBuffAlertEnabled('personal','motw',true); assert(B:ImportSettings(text)); assert(not B:BuffAlertEnabled('personal','motw') and B.db.buffAlerts.personal.motw.sound=='harp'); B:InitDB(); assert(not B:BuffAlertEnabled('personal','motw'))")
test('Other-class import does not replace this class buff sounds',BASE+"B:SetBuffAlertEnabled('personal','motw',false); local text=B:ExportSettings():gsub('BuffTap1:DRUID:','BuffTap1:MAGE:',1); assert(B:ImportSettings(text)); assert(not B:BuffAlertEnabled('personal','motw'))")
test('Mute tooltip explains scope default sound and visual availability',BASE+"B:SetBuffAlertEnabled('personal','motw',false); local t=B:BuffAlertTooltip('personal','motw'); assert(t:find('muted') and t:find('personal') and t:find('Visual reminders') and t:find('default reminder sound')); B:Refresh(); local lines={}; GameTooltip.AddLine=function(_,text) lines[#lines+1]=text end; B.button.scripts.OnEnter(); assert(table.concat(lines,' '):find('Sound muted for this buff'))")
test('Personal speaker remains configurable for unlearned class spells',BASE+"B:Options(); local row; for _,r in ipairs(B.options.buffRows) do if r.def.key=='aquatic-form' then row=r end end; assert(row and row.sound); row.sound.scripts.OnClick(row.sound); assert(not B:BuffAlertEnabled('personal','aquatic-form')); assert(B:BuffAlertEnabled('personal','motw'))")
test('Standard group switches edit only selected Party or Raid buff',BASE+"B:Options(); local f=B.options; f.groupContext='Party'; B:Options(); local row=f.assignRows[1]; assert(row and row.sound.soundOn==true); row.sound.scripts.OnClick(row.sound); assert(not B:BuffAlertEnabled('party',row.def)); f.groupContext='Raid'; B:Options(); assert(row.sound.soundOn==true and B:BuffAlertEnabled('personal',row.def))")
for cls in ('WARRIOR','PALADIN','HUNTER','ROGUE','PRIEST','SHAMAN','MAGE','WARLOCK','DRUID'):
 test('Sound controls construct for '+cls,BASE+"playerClass='"+cls+"'; B:InitDB(); B:Options(); assert(B.options.categorySounds.reminder and B.options.categorySounds.cleanse); for _,r in ipairs(B.options.buffRows) do assert(r.sound) end" )
test('Paladin Party and Raid sound panel includes unlearned blessings',BASE+"playerClass='PALADIN'; B:InitDB(); B:Options(); local f=B.options; f.blessingContext='Party'; B:ToggleBlessingSounds(); assert(f.blessingSounds.context=='party'); local c=f.blessingSounds.checks.bok; assert(c); c.scripts.OnClick(c); assert(not B:BuffAlertEnabled('party','bok') and B:BuffAlertEnabled('raid','bok')); B:ToggleBlessingSounds(); f.blessingContext='Raid'; B:ToggleBlessingSounds(); assert(c.soundOn==true)")
for kind,field in [('reminder','sound'),('supply','suppliesSound'),('camp','campSound'),('cleanse','cleanseSoundEnabled'),('social','socialSoundEnabled')]:
 test('Category '+kind+' mute blocks automatic sound but permits preview',BASE+"B:SetAlertCategoryEnabled('"+kind+"',false); assert(not B:PlayAlert('"+kind+"')); assert(heard==0); assert(B:PlayAlert('"+kind+"',true) and heard==1); B:SetAlertCategoryEnabled('"+kind+"',true); B.lastAlertSound=nil; assert(B:PlayAlert('"+kind+"') and heard==2)")
test('Cleanse remains audible when ordinary Reminder category is off',BASE+"B.db.sound=false; B.db.cleanseSoundEnabled=true; local a={source='cleanse',key='cleanse:test',id=5232,name='Cleanse',rank='',target='player',targetGUID=UnitGUID('player'),targetName='You',reason='test',valid=true,secureType='spell'}; B:Commit(a,'cleanse'); assert(heard==1 and B.lastAlertInfo.kind=='cleanse')")
test('Category permissions preserve existing migration states',BASE+"B.db.sound=false; B.db.cleanseSoundEnabled=nil; B.db.socialSoundEnabled=nil; B:NormalizeAlerts(); assert(not B.db.cleanseSoundEnabled and B.db.socialSoundEnabled); B.db.cleanseSoundEnabled=true; B:NormalizeAlerts(); assert(B.db.cleanseSoundEnabled)")
test('SmartShift remains silent regardless of category and queue state',BASE+"local a={source='smartshift',key='smartshift:5232',id=5232,name='Return',rank='',target='player',targetGUID=UnitGUID('player'),targetName='You',reason='test',valid=true,secureType='spell'}; B:Commit(a,'return'); assert(heard==0); assert(B:BuffAlertMuteReason(a):find('always silent'))")
test('Category speaker button updates only its own setting',BASE+"B:Options(); local f=B.options; local t=f.categorySounds.reminder; local camp=B.db.campSound; t.scripts.OnClick(t); assert(not B.db.sound and B.db.campSound==camp)")

FRESH="local B=BuffTap; B.db.onboardingVersion=nil; B.db.welcomeSeen=false; B:ShowOnboarding(); "
for enabled in ('true','false'):
 test('Fresh setup applies all sound category permissions '+enabled,FRESH+"B.onboarding.quickSelection.sounds="+enabled+"; assert(B:ApplyFirstRunSetup(B.onboarding.quickSelection)); for _,kind in ipairs({'reminder','supply','camp','cleanse','social'}) do assert(B:AlertCategoryEnabled(kind)=="+enabled+") end; assert(not B.db.nearbySocialAlert)")
test('Returning setup review leaves individual category choices intact',"local B=BuffTap; B.db.welcomeSeen=true; B.db.campSound=false; B.db.cleanseSoundEnabled=true; B:ShowOnboarding(true); B.onboarding.quickSelection.sounds=true; assert(B:ApplyFirstRunSetup(B.onboarding.quickSelection)); assert(not B.db.campSound and B.db.cleanseSoundEnabled)")

GEOMETRY="""
local B=BuffTap; local old=CreateFrame; local frames={}
CreateFrame=function(...)
 local f=old(...); frames[#frames+1]=f
 local point=f.SetPoint; f.SetPoint=function(self,...) local args={...}; if args[1]=='TOPLEFT' and type(args[#args-1])=='number' then self.testX=args[#args-1]; self.testY=args[#args] end; point(self,...) end
 return f
end
B:Options(); CreateFrame=old
"""
test('Speaker and shortened timing controls stay in separate row columns',GEOMETRY+"local r=B.options.buffRows[1]; assert(r.rebuff.testX+r.rebuff.width<=r.default.testX); assert(r.default.testX+r.default.width<r.sound.testX); assert(r.sound.testX+r.sound.width<r.up.testX)")
test('Default sounds card has evenly spaced bounded preview and speaker pairs',GEOMETRY+"local count=0; for _,f in ipairs(frames) do if f.text=='Preview' and f.testX==510 then count=count+1; assert(f.width==124) end end; assert(count==5); local previous; for _,kind in ipairs({'reminder','supply','camp','cleanse','social'}) do local c=B.options.categorySounds[kind]; assert(c.testX==644 and c.width==44 and c.testX+c.width==688); if previous then assert(previous-c.testY==36) end; previous=c.testY end; assert(not B.options.soundCheck.shown)")

test('Explicit same-class profile copy includes buff mutes and reserved sound',BASE+"local original=B.profileDB:GetCurrentProfile(); local who=B.profileDB.keys.char; B:SetBuffAlertEnabled('personal','motw',false); B.db.buffAlerts.personal.motw.sound='harp'; B:SaveClassSetup(); assert(B:CreateSettingsProfile('Sound copy test',false)); B:SetBuffAlertEnabled('personal','motw',true); assert(B:CopySettingsProfile(original,who)); assert(not B:BuffAlertEnabled('personal','motw') and B.db.buffAlerts.personal.motw.sound=='harp')")

test('Speaker glyph uses active accent on and muted colour off',BASE+"local T=B.OptionsTheme; local c=CreateFrame('Button'); c.glyph=c:CreateTexture(); local colour; c.glyph.SetVertexColor=function(_,r,g,b) colour={r,g,b} end; T.SoundSpeaker(c,true); assert(c.soundOn and colour[1]==T.accent[1] and colour[2]==T.accent[2] and colour[3]==T.accent[3]); T.SoundSpeaker(c,false); assert(not c.soundOn and colour[1]==T.muted[1] and c.glyph.texture:find('Muted'))")
test('Party Raid speaker fits top right without covering buff heading',GEOMETRY+"local r=B.options.assignRows[1]; assert(r.sound.kind=='Button' and r.sound.testX==424 and r.sound.testY==-4 and r.sound.width==26 and r.sound.testX+r.sound.width<=r.width-8)")
